#define _CRT_SECURE_NO_WARNINGS#include <locale.h>#include <stdio.h>#include <stdlib.h>int pogruzka(int A, int B, int C){    int condition;    condition = ((A % 5 == 0) && (B % 5 == 0) && (C % 5 == 0));    return condition;}int main() {    setlocale(LC_ALL, "RUS");    int A, B, C;    int condition;    printf("=== Контроль погрузки ===\n");    printf("Введите вес трех грузов в кг (груз 1, груз 2 , груз 3): ");    scanf("%d %d %d", &A, &B, &C);    condition = pogruzka(A, B, C);    printf("Погрузка разрешена (1 - да, 0 - нет): %d\n", condition);}